using Lockflight.Cli.Review;

namespace Lockflight.Cli.Tests.Review;

public sealed class ReproductionBuildTests
{
    [Fact]
    public void EachReproductionGetsItsOwnClassAndFileNameForErrors()
    {
        string source = ReproductionBuild.Source(
            [new ReproductionCandidate(0, "First", "[Fact]\r\npublic void First() { }"), new ReproductionCandidate(2, "Third", "[Fact]\npublic void Third() { }")],
            ["using Shop;", "using Xunit;"],
            "/tmp/lfr-1");

        Assert.Equal(
            """
            // <auto-generated/>
            #nullable enable
            using Shop;
            using Xunit;

            namespace LockflightReproductions;

            public sealed class Finding1
            {
            #line 1 "/tmp/lfr-1/Finding1.cs"
            [Fact]
            public void First() { }
            #line default
            }

            public sealed class Finding3
            {
            #line 1 "/tmp/lfr-1/Finding3.cs"
            [Fact]
            public void Third() { }
            #line default
            }


            """.ReplaceLineEndings("\n"),
            source);
    }

    [Fact]
    public void AnErrorOnAUsingLineNamesThatUsing()
    {
        Assert.Equal(1, ReproductionBuild.UsingAt(new CompileError(TestProjectProfiles.GeneratedFileName, 4, 7, "CS0246", "Moq"), 2));
        Assert.Null(ReproductionBuild.UsingAt(new CompileError(TestProjectProfiles.GeneratedFileName, 9, 1, "CS1022", "brace"), 2));
        Assert.Null(ReproductionBuild.UsingAt(new CompileError("Finding1.cs", 3, 1, "CS0246", "Moq"), 2));
    }
}
